I’m writing a small inventory reconciler, but this gives the wrong result and changes `stock`. What’s going wrong?

```python
def reconcile(current, updates):
    for item, qty in updates.items():
        if not qty:
            current.pop(item, None)
        else:
            current[item] = qty
    return current

stock = {'pen': 2, 'tape': 1}
updates = {'pen': 0, 'tape': None}
# Expected: {'pen': 0}; stock must remain unchanged.
```

`if not qty` treats both `0` and `None` as false, so it removes both items. The function also modifies `current` directly, which changes the original `stock` dictionary.

Make a copy and check explicitly for `None`:

```python
def reconcile(current, updates):
    result = current.copy()
    for item, qty in updates.items():
        if qty is None:
            result.pop(item, None)
        else:
            result[item] = qty
    return result
```

This returns `{'pen': 0}` and leaves `stock` unchanged.

Validate the existing entries and each update, while keeping duplicate detection and patch behavior:

```python
from collections.abc import Mapping

def reconcile(current, updates):
    def validate(item, qty, *, allow_none):
        if not isinstance(item, str) or not item:
            raise ValueError(f"Invalid key: {item!r}")
        if qty is None and allow_none:
            return
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 0:
            raise ValueError(f"Invalid quantity for {item!r}: {qty!r}")

    for item, qty in current.items():
        validate(item, qty, allow_none=False)

    result = current.copy()
    seen = set()
    pairs = updates.items() if isinstance(updates, Mapping) else updates

    for item, qty in pairs:
        validate(item, qty, allow_none=True)
        if item in seen:
            raise ValueError(f"Duplicate update for {item!r}")
        seen.add(item)

        if qty is None:
            result.pop(item, None)
        else:
            result[item] = qty

    return result
```

This assumes `current` is a dictionary and updates are a mapping or well-formed iterable of pairs. It leaves `current` unchanged, including when validation fails.

```python
from collections.abc import Mapping
import unittest


def reconcile(current, updates):
    def validate(key, qty, allow_none):
        if not isinstance(key, str) or not key:
            raise ValueError('Invalid key')
        if qty is None and allow_none:
            return
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 0:
            raise ValueError('Invalid quantity')

    for key, qty in current.items():
        validate(key, qty, False)

    result = current.copy()
    seen = set()
    pairs = updates.items() if isinstance(updates, Mapping) else updates
    for key, qty in pairs:
        validate(key, qty, True)
        if key in seen:
            raise ValueError('Duplicate key')
        seen.add(key)
        if qty is None:
            result.pop(key, None)
        else:
            result[key] = qty
    return result


class ReconcileTests(unittest.TestCase):
    def test_patch_and_inputs(self):
        current = {'pen': 2, 'tape': 1, 'book': 4}
        updates = [('pen', 0), ('tape', None), ('missing', None)]
        self.assertEqual(reconcile(current, iter(updates)), {'pen': 0, 'book': 4})
        self.assertEqual(current, {'pen': 2, 'tape': 1, 'book': 4})
        self.assertEqual(updates, [('pen', 0), ('tape', None), ('missing', None)])

    def test_duplicate_and_invalid_updates_preserve_inputs(self):
        for bad in [[('pen', 1), ('pen', 1)],
                    [('pen', 1), ('', 2)], [('pen', 1), (1, 2)],
                    [('pen', 1), ('x', -1)], [('pen', 1), ('x', True)],
                    [('pen', 1), ('x', 1.5)]]:
            with self.subTest(bad=bad):
                current = {'pen': 2}
                before = bad.copy()
                with self.assertRaises(ValueError):
                    reconcile(current, bad)
                self.assertEqual(current, {'pen': 2})
                self.assertEqual(bad, before)

    def test_invalid_current(self):
        for current in ({'': 1}, {1: 1}, {'x': None}, {'x': -1},
                        {'x': False}, {'x': 1.5}):
            with self.subTest(current=current):
                before = current.copy()
                with self.assertRaises(ValueError):
                    reconcile(current, [])
                self.assertEqual(current, before)


if __name__ == '__main__':
    unittest.main()
```

Run the file with Python. A one-shot iterator is consumed as it is read, including up to a failure; its underlying list is not changed. Pair entries are assumed well formed.
